<script setup lang="ts">import{ref}from'vue';import{api,type ApiError}from'../api';const message=ref('待完成');async function submitAll(){try{const poll=localStorage.getItem('yk-poll-id'),option=localStorage.getItem('yk-poll-option-id'),assignment=localStorage.getItem('yk-assignment-id'),quiz=localStorage.getItem('yk-quiz-id');if(poll&&option)await api(`/api/v1/polls/${poll}/answers`,{method:'POST',body:JSON.stringify({option_id:option})},'student');if(assignment)await api(`/api/v1/assignments/${assignment}/submit`,{method:'POST',body:JSON.stringify({answers:{'question-b-rsa-1':'公钥'},raw_score:10,max_score:10})},'student');if(quiz){const attempt=await api<{attempt_id:string}>(`/api/v1/quizzes/${quiz}/attempts`,{method:'POST'},'student');await api(`/api/v1/quizzes/${quiz}/attempts/${attempt.attempt_id}/submit`,{method:'POST',body:JSON.stringify({answers:{},raw_score:8,max_score:10})},'student')}message.value='投票、作业和测验均已提交'}catch(e){message.value=(e as ApiError).message}}</script>
<template><div><div class="hero"><div><h1>作业与测验</h1><p>理论与实验后的练习关联当前课时。</p></div></div><p data-testid="student-work-message" class="status-ok">{{message}}</p><div class="grid grid-2"><section class="card"><div class="row-between"><b>RSA 课后作业</b><span class="badge">已发布</span></div><div class="card"><b>单选题</b><p>RSA 算法中用于公开给通信对方的是哪一类密钥？</p></div><button class="yk-button primary" style="width:100%" @click="submitAll">提交投票、作业与测验</button></section><section class="card"><h3>课堂小测</h3><p class="muted">4 题 · 10 分钟 · 客观题原始分自动记录。</p></section></div></div></template>
